def entry_for(scope,cik,document_hash):
    from .sec_html_reviewed import plan_for
    entry=deepcopy(REGISTERED.get(scope))
    if not entry:raise ValueError('Unknown reviewed addition scope')
    plan=entry['plan'];base=plan_for(document_hash,cik)
    if (not base or base['plan_hash']!=entry['parent_plan_hash']
            or plan['cik']!=str(int(cik)).zfill(10) or plan['document_hash']!=document_hash
            or plan.get('source_mode')!=base.get('source_mode')):
        raise ValueError('Reviewed addition parent/source differs')
    body=deepcopy(entry);body['plan'].pop('plan_hash');body['plan'].pop('review_scope_id')
    if digest(body)!=scope:raise ValueError('Reviewed addition seal differs')
    old={digest(f['locator']) for f in base['facts']}
    new=[digest(f['locator']) for f in plan['facts']]
    if old.intersection(new) or len(set(new))!=len(new):
        raise ValueError('Reviewed addition repeats a selected source cell')
    return entry
